/* HEXA BATTLEGROUNDS upgrade2 — PART 1 OF 32. For databases that already ran supabase/upgrade (match phases); Run in order. Safe to re-run. */ alter table teams add column if not exists pos_x real; alter table teams add column if not exists pos_y real; alter table teams add column if not exists pos_at timestamptz; alter table teams add column if not exists travel_fx real; alter table teams add column if not exists travel_fy real; alter table teams add column if not exists zone_hit_at timestamptz; alter table teams add column if not exists last_steer_ping timestamptz; alter table arenas add column if not exists red_x real; alter table arenas add column if not exists red_y real; alter table arenas add column if not exists red_r real; alter table arenas add column if not exists red_at timestamptz; alter table arenas add column if not exists last_red_at timestamptz; alter table battles add column if not exists x real; alter table battles add column if not exists y real; create or replace function _defaults() returns jsonb language sql immutable as $$ select jsonb_build_object( 'pts_standard', 100, 'pts_hard', 150, 'pts_battle', 125, 'pts_airdrop', 75, 'pts_relay_bonus', 25, 'pts_relocation', 40, 'pen_recovery', 40, 'finale_max', 300, 'finale_entry_max', 200, 'finale_exchange_max', 200, 'hp_max', 100, 'hp_respawn', 50, 'dmg_fail', 10, 'dmg_zone', 15, 'shield_max', 60, 'shuttle_seconds', 10, 'roles_seconds', 15, 'bus_size', 3, 'arena_size', 15, 'attack_cooldown', 90, 'protect_seconds', 120, 'recovery_seconds', 120, 'zone_warning', 60, 'airdrop_window', 180, 'airdrop_interval', 0, 'intel_fallback', 90, 'relay_chance', 20, 'hint_cost', 15, 'alliance_minutes', 10, 'alliance_cost', 10, 'chat_limit', 6, 'drop_seconds', 8, 'visit_missions', 2, 'zone_auto', 0, 'zone_schedule', '20,40,55,70,85', 'sync_seconds', 0, 'auto_pacing', 0, 'phase_schedule', '2,12,30,50', 'duel_phase', 2, 'mission_time_pct', 100, 'pin_length', 6, 'move_speed', 25, 'loc_radius', 35, 'engage_range', 60, 'zone_tick_seconds', 6, 'zone_tick_damage', 4, 'red_interval', 0, 'red_warning', 20, 'red_damage', 30, 'red_radius', 80 ) $$; create or replace function _loc_xy(p_loc text) returns float8[] language sql stable as $$ select array[x::float8, y::float8] from locations where id = p_loc $$; create or replace function _team_xy(t teams) returns float8[] language plpgsql stable as $$ declare d float8[]; p float8; begin if t.state = 'traveling' and t.travel_to is not null and t.travel_arrive_at is not null then d := _loc_xy(t.travel_to); if t.travel_fx is not null and d is not null then p := least(1, greatest(0, extract(epoch from now() - t.travel_started_at) / greatest(0.001, extract(epoch from t.travel_arrive_at - t.travel_started_at)))); return array[t.travel_fx + (d[1] - t.travel_fx) * p, t.travel_fy + (d[2] - t.travel_fy) * p]; end if; end if; if t.pos_x is not null then return array[t.pos_x::float8, t.pos_y::float8]; end if; return coalesce(_loc_xy(t.location_id), array[0.5, 0.93]); end $$; create or replace function _teams_pos_sync() returns trigger language plpgsql as $$ declare xy float8[]; begin if tg_op = 'INSERT' or (new.location_id is distinct from old.location_id and new.pos_x is not distinct from old.pos_x and new.pos_y is not distinct from old.pos_y) then if new.location_id is not null then xy := _loc_xy(new.location_id); if xy is not null then new.pos_x := xy[1]; new.pos_y := xy[2]; new.pos_at := now(); end if; end if; end if; return new; end $$; drop trigger if exists teams_pos_sync on teams; create trigger teams_pos_sync before insert or update on teams for each row execute function _teams_pos_sync(); update teams t set pos_x = l.x, pos_y = l.y, pos_at = now() from locations l where l.id = t.location_id and t.pos_x is null; create or replace function _zone_circle(p_event uuid, p_stage int) returns float8[] language plpgsql stable as $$ declare radii float8[] := array[0.9, 0.5, 0.36, 0.24, 0.14, 0.035]; tr float8[]; seed int; cx float8 := 0.5; cy float8 := 0.5; nx float8; ny float8; ang float8; mag float8; d float8; room float8; k int; begin tr := coalesce(_loc_xy('tr14'), array[0.5, 0.65]); select mission_seed into seed from events where id = p_event; p_stage := greatest(0, least(5, coalesce(p_stage, 0))); for k in 1..p_stage loop if k = 5 then cx := tr[1]; cy := tr[2]; exit; end if; ang := (abs(hashtext(coalesce(seed, 0)::text || 'zang' || k)) % 3600) / 3600.0 * 2 * pi(); mag := (abs(hashtext(coalesce(seed, 0)::text || 'zmag' || k)) % 1000) / 1000.0 * 0.45 * radii[k + 1]; nx := tr[1] + cos(ang) * mag; ny := tr[2] + sin(ang) * mag; room := radii[k] - radii[k + 1]; d := sqrt((nx - cx) ^ 2 + (ny - cy) ^ 2); if d > room and d > 0 then nx := cx + (nx - cx) * room / d; ny := cy + (ny - cy) * room / d; end if; while sqrt((nx - tr[1]) ^ 2 + (ny - tr[2]) ^ 2) > radii[k + 1] * 0.7 loop nx := nx + (tr[1] - nx) * 0.3; ny := ny + (tr[2] - ny) * 0.3; end loop; cx := nx; cy := ny; end loop; return array[cx, cy, radii[p_stage + 1]]; end $$; create or replace function _in_circle(c float8[], x float8, y float8) returns boolean language sql immutable as $$ select c is null or sqrt((x - c[1]) ^ 2 + (y - c[2]) ^ 2) <= c[3] $$; create or replace function _nearest_safe_xy(p_event uuid, p_stage int, p_x float8, p_y float8) returns text language sql stable as $$ select id from locations where enabled and kind <> 'start' and _in_circle(_zone_circle(p_event, p_stage), x, y) order by _in_circle(_zone_circle(p_event, least(5, p_stage + 1)), x, y) desc, (x - p_x) ^ 2 + (y - p_y) ^ 2 limit 1 $$; create or replace function _zone_publish(p_arena uuid) returns void language plpgsql as $$ declare a arenas; cur float8[]; nxt float8[]; begin select * into a from arenas where id = p_arena; if a.id is null then return; end if; cur := _zone_circle(a.event_id, a.zone_stage); if a.zone_next_at is not null and a.zone_stage < 5 then nxt := _zone_circle(a.event_id, a.zone_stage + 1); end if; update arenas set overlay = (overlay - 'zone' - 'red') || jsonb_build_object( 'zone', jsonb_build_object('stage', a.zone_stage, 'cur', to_jsonb(cur), 'next', to_jsonb(nxt), 'next_at', a.zone_next_at), 'world', jsonb_build_object('speed', _cfg(a.event_id, 'move_speed') / 1000.0, 'loc_radius', _cfg(a.event_id, 'loc_radius') / 1000.0, 'engage_range', _cfg(a.event_id, 'engage_range') / 1000.0)) || case when a.red_at is not null then jsonb_build_object('red', jsonb_build_object('x', a.red_x, 'y', a.red_y, 'r', a.red_r, 'at', a.red_at)) else '{}'::jsonb end where id = p_arena; end $$; create or replace function _loc_at(p_event uuid, p_x float8, p_y float8) returns text language sql stable as $$ select id from locations where enabled and kind <> 'start' and (x - p_x) ^ 2 + (y - p_y) ^ 2 <= (_cfg(p_event, 'loc_radius') / 1000.0) ^ 2 order by (x - p_x) ^ 2 + (y - p_y) ^ 2 limit 1 $$;
